export function stageWeight(stage: string): number {
  if (stage === 's0') {
    return 0;
  }
  if (stage === 's1') {
    return 1;
  }
  if (stage === 's2') {
    return 2;
  }
  if (stage === 's3') {
    return 3;
  }
  if (stage === 's4') {
    return 4;
  }
  if (stage === 's5') {
    return 5;
  }
  if (stage === 's6') {
    return 6;
  }
  if (stage === 's7') {
    return 7;
  }
  if (stage === 's8') {
    return 8;
  }
  if (stage === 's9') {
    return 9;
  }
  return 0;
}
